<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
use School\Services\AuditService;

SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);if(!SchoolAuth::hasPermission('attendance.view')){http_response_code(403);exit('Attendance access is not permitted.');}
$pdo=SchoolDatabase::connection();$activeYear=$pdo->query("SELECT id,name FROM academic_years WHERE status='active' ORDER BY starts_on DESC LIMIT 1")->fetch();$yearId=(int)($activeYear['id']??0);$error='';
$canRecord=SchoolAuth::hasPermission('attendance.manage');
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!SchoolAuth::verifyCsrf())$error='Your session expired. Please try again.';
 elseif(!$canRecord){http_response_code(403);exit('Attendance entry is not permitted.');}
 else{
  $classId=(int)($_POST['class_group_id']??0);$sessionDate=(string)($_POST['session_date']??'');$marks=$_POST['attendance']??[];
  if(!$yearId)$error='Set an active academic year before taking attendance.';
  elseif(!$classId||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$sessionDate)||$sessionDate>date('Y-m-d'))$error='Choose a valid class and attendance date.';
  else try{
   $classCheck=$pdo->prepare("SELECT c.id FROM class_groups c WHERE c.id=:class AND c.academic_year_id=:year");$classCheck->execute(['class'=>$classId,'year'=>$yearId]);if(!$classCheck->fetchColumn())throw new RuntimeException('That class is not in the active academic year.');
   if(in_array($role,['class_teacher','subject_teacher'],true)){$q=$pdo->prepare("SELECT COUNT(*) FROM teacher_assignments ta JOIN staff s ON s.id=ta.staff_id WHERE s.user_id=:user AND s.employment_status='active' AND ta.class_group_id=:class AND ta.academic_year_id=:year AND ta.ended_at IS NULL");$q->execute(['user'=>(int)$user['id'],'class'=>$classId,'year'=>$yearId]);if(!(int)$q->fetchColumn())throw new RuntimeException('You are not assigned to this class.');}
   $studentsQuery=$pdo->prepare("SELECT s.id FROM enrollments e JOIN students s ON s.id=e.student_id WHERE e.class_group_id=:class AND e.academic_year_id=:year AND e.status='active' AND s.status='active' ORDER BY s.full_name");$studentsQuery->execute(['class'=>$classId,'year'=>$yearId]);$studentIds=array_map('intval',array_column($studentsQuery->fetchAll(),'id'));if(!$studentIds)throw new RuntimeException('This class has no active students to mark.');
   $validStates=['present','absent','late','excused','early_departure'];foreach($studentIds as $studentId)if(!isset($marks[$studentId])||!in_array($marks[$studentId],$validStates,true))throw new RuntimeException('Select an attendance state for every student.');
   SchoolDatabase::transaction(function(PDO $pdo)use($classId,$sessionDate,$studentIds,$marks,$user):void{$q=$pdo->prepare("INSERT INTO attendance_sessions (class_group_id,stream_id,session_date,period_label,taken_by) VALUES (:class,NULL,:date,'Daily',:user)");$q->execute(['class'=>$classId,'date'=>$sessionDate,'user'=>(int)$user['id']]);$sessionId=(int)$pdo->lastInsertId();$record=$pdo->prepare('INSERT INTO attendance_records (session_id,student_id,state,recorded_by) VALUES (:session,:student,:state,:user)');foreach($studentIds as $studentId)$record->execute(['session'=>$sessionId,'student'=>$studentId,'state'=>$marks[$studentId],'user'=>(int)$user['id']]);(new AuditService())->record((int)$user['id'],'attendance.session.record','attendance_sessions',$sessionId,['class_group_id'=>$classId,'session_date'=>$sessionDate,'students_marked'=>count($studentIds)]);});
   school_flash('success','Attendance saved for '.count($studentIds).' students.');header('Location: '.SCHOOL_BASE_URL.'attendance/index.php?class_id='.$classId.'&date='.urlencode($sessionDate));exit;
  }catch(Throwable $exception){$error=$exception instanceof PDOException?'Attendance was already recorded for this class and date. Corrections require an authorized workflow.':$exception->getMessage();}
 }
}
$classes=[];
if($yearId){if(in_array($role,['class_teacher','subject_teacher'],true)){$q=$pdo->prepare("SELECT DISTINCT c.id,c.name FROM teacher_assignments ta JOIN staff s ON s.id=ta.staff_id JOIN class_groups c ON c.id=ta.class_group_id WHERE s.user_id=:user AND s.employment_status='active' AND ta.academic_year_id=:year AND ta.ended_at IS NULL ORDER BY c.name");$q->execute(['user'=>(int)$user['id'],'year'=>$yearId]);$classes=$q->fetchAll();}else{$q=$pdo->prepare('SELECT id,name FROM class_groups WHERE academic_year_id=:year ORDER BY name');$q->execute(['year'=>$yearId]);$classes=$q->fetchAll();}}
$classId=(int)($_GET['class_id']??$_POST['class_group_id']??0);$sessionDate=(string)($_GET['date']??$_POST['session_date']??date('Y-m-d'));
$selectedClass=null;foreach($classes as $class)if((int)$class['id']===$classId)$selectedClass=$class;
$studentRows=[];$existing=[];
if($canRecord&&$selectedClass){$q=$pdo->prepare("SELECT s.id,s.admission_number,s.full_name,s.gender FROM enrollments e JOIN students s ON s.id=e.student_id WHERE e.class_group_id=:class AND e.academic_year_id=:year AND e.status='active' AND s.status='active' ORDER BY s.full_name");$q->execute(['class'=>$classId,'year'=>$yearId]);$studentRows=$q->fetchAll();$q=$pdo->prepare("SELECT ar.student_id,ar.state FROM attendance_records ar JOIN attendance_sessions sess ON sess.id=ar.session_id WHERE sess.class_group_id=:class AND sess.session_date=:date AND sess.period_label='Daily'");$q->execute(['class'=>$classId,'date'=>$sessionDate]);foreach($q->fetchAll() as $row)$existing[(int)$row['student_id']]=$row['state'];}
$history=[];if(!$canRecord){$scope=$role==='parent_guardian'?"JOIN student_guardians sg ON sg.student_id=s.id JOIN guardians g ON g.id=sg.guardian_id WHERE g.user_id=:user AND sg.verification_status='verified' AND sg.ended_at IS NULL":"WHERE s.user_id=:user";$q=$pdo->prepare("SELECT sess.session_date,s.full_name,s.admission_number,ar.state FROM attendance_records ar JOIN attendance_sessions sess ON sess.id=ar.session_id JOIN students s ON s.id=ar.student_id {$scope} ORDER BY sess.session_date DESC,s.full_name LIMIT 100");$q->execute(['user'=>(int)$user['id']]);$history=$q->fetchAll();}
$schoolRole=$role;$schoolName=(string)($pdo->query('SELECT name FROM school_profile ORDER BY id LIMIT 1')->fetchColumn()?:'School Management');$pageTitle='Attendance';require __DIR__.'/../includes/header.php';
?>
<div class="page-head"><div><h4>Attendance</h4><p><?= $canRecord?'Record daily attendance for an assigned class.':'Attendance history for records linked to your account.' ?> <?= $activeYear?'· '.e($activeYear['name']):'' ?></p></div></div>
<?php if($error!==''): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<?php if($canRecord): ?>
<div class="card mb-3"><div class="card-header"><span class="card-title-sm"><i class="bi bi-calendar2-check-fill me-1"></i>Choose class and date</span></div><div class="card-body"><form method="get" class="row g-2 align-items-end"><div class="col-md-5"><label class="form-label">Class</label><select class="form-select" name="class_id" required><option value="">Choose class</option><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>" <?= (int)$class['id']===$classId?'selected':'' ?>><?= e($class['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Date</label><input class="form-control" type="date" name="date" value="<?= e($sessionDate) ?>" max="<?= e(date('Y-m-d')) ?>" required></div><div class="col-md-3"><button class="btn btn-outline-primary w-100"><i class="bi bi-search me-1"></i>Load register</button></div></form></div></div>
<?php if(!$yearId): ?><div class="empty-state"><i class="bi bi-calendar-x"></i><strong>No active academic year</strong><p>Set up a year and class before recording attendance.</p><?php if(SchoolAuth::hasPermission('school.manage')): ?><a class="btn btn-primary btn-sm" href="<?= SCHOOL_BASE_URL ?>settings/academic.php">Set up academic structure</a><?php endif; ?></div>
<?php elseif(!$classes): ?><div class="empty-state"><i class="bi bi-door-open"></i><strong>No available classes</strong><p>Classes must be configured in the active academic year, and teachers need an assignment.</p></div>
<?php elseif($selectedClass): ?>
<div class="card"><div class="card-header d-flex justify-content-between align-items-center"><span class="card-title-sm">Daily register · <?= e($selectedClass['name']) ?> · <?= e(formatDate($sessionDate)) ?></span><?php if($existing): ?><span class="pill pill-green"><i class="bi bi-check-circle-fill"></i> Already recorded</span><?php endif; ?></div>
<?php if($existing): ?><div class="alert alert-info m-3 mb-0">This register has already been saved. The correction workflow will be added with academic approvals; records have not been overwritten.</div><?php endif; ?>
<?php if(!$studentRows): ?><div class="empty-state"><i class="bi bi-people"></i><strong>No enrolled students in this class</strong><p>Register students and assign them to this academic year first.</p></div>
<?php elseif(!$existing): ?><form method="post"><?= SchoolAuth::csrfField() ?><input type="hidden" name="class_group_id" value="<?= $classId ?>"><input type="hidden" name="session_date" value="<?= e($sessionDate) ?>"><div class="table-wrap"><table class="table table-hover align-middle mb-0"><thead><tr><th>Admission no.</th><th>Student</th><th>Status</th></tr></thead><tbody><?php foreach($studentRows as $student): ?><tr><td><span class="ref"><?= e($student['admission_number']) ?></span></td><td><span class="name"><?= e($student['full_name']) ?></span></td><td><select class="form-select form-select-sm" name="attendance[<?= (int)$student['id'] ?>]" required><option value="">Choose status</option><option value="present">Present</option><option value="absent">Absent</option><option value="late">Late</option><option value="excused">Excused</option><option value="early_departure">Early departure</option></select></td></tr><?php endforeach; ?></tbody></table></div><div class="p-3 border-top d-flex justify-content-end"><button class="btn btn-primary"><i class="bi bi-check2-circle me-1"></i>Save attendance</button></div></form><?php endif; ?></div>
<?php endif; ?>
<?php else: ?>
<div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-clock-history me-1"></i>Attendance history</span></div><div class="table-wrap"><table class="table table-hover align-middle mb-0"><thead><tr><th>Date</th><th>Admission no.</th><th>Student</th><th>Status</th></tr></thead><tbody><?php if(!$history): ?><tr><td colspan="4"><div class="empty-state"><i class="bi bi-calendar2-x"></i><strong>No attendance history</strong><p>Records will appear when attendance is entered for linked students.</p></div></td></tr><?php endif; foreach($history as $row): ?><tr><td><?= e(formatDate($row['session_date'])) ?></td><td><span class="ref"><?= e($row['admission_number']) ?></span></td><td><?= e($row['full_name']) ?></td><td><span class="pill <?= $row['state']==='present'?'pill-green':($row['state']==='absent'?'pill-red':'pill-gold') ?>"><?= e(ucwords(str_replace('_',' ',$row['state']))) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php endif; ?>
<?php require __DIR__.'/../includes/footer.php'; ?>
